//----------- PersistedInstance ------------------------------------------------

/// The instance of a zone that was current/published the last time Cascade was
/// running.
///
/// This type holds information about the [`CurrentInstance`] from the
/// _previous_ invocation of Cascade. On startup, Cascade will try to restore
/// that instance from disk; on success, this will become the current instance.
#[derive(Debug, Clone)]
pub struct PersistedInstance {
    /// The loaded instance.
    ///
    /// This describes the instance loaded from the zone source.
    pub loaded: LoadedInstance,

    /// The signed instance.
    ///
    /// This describes the signed instance generated by Cascade.
    pub signed: SignedInstance,

    /// When the instance was published.
    pub pub_time: SystemTime,
}

impl PersistedInstance {
    /// Build a [`CurrentInstance`] out of `self`.
    pub fn to_current(&self) -> CurrentInstance {
        let Self {
            loaded,
            signed,
            pub_time,
        } = self.clone();

        CurrentInstance {
            loaded,
            signed,
            pub_time,
        }
    }
}

//----------- LoadedInstance ---------------------------------------------------

/// A loaded instance of a zone.
#[derive(Debug, Clone)]
pub struct LoadedInstance {
    /// The ID of this instance.
    pub id: LoadedInstanceId,

    /// The next usable signed instance ID relative to this.
    pub next_signed_id: u64,

    /// The SOA record of this instance.
    ///
    /// The primary purpose of this field is to provide the SOA serial. We still
    /// store the full SOA because it is used sometimes, e.g. for sending IXFRs.
    pub soa: SoaRecord,

    /// The number of loaded records.
    ///
    /// This is the number of records in this instance. This includes any DNSSEC
    /// records (RRSIG, NSEC, etc.) in the instance, even if they will not be
    /// part of the signed instance. Notably, this also includes the SOA record.
    pub num_records: NonZeroU64,
    //
    // TODO:
    // - How the instance was loaded (time, source, duration, size).
    // - Whether the zone contains DNSSEC records (for pass-through mode).
    // - Basic details of the zone:
    //   - How many NS / DS / glue records are in the zone.
    //   - Total memory usage.
}

impl LoadedInstance {
    /// The SOA serial of this instance.
    pub fn serial(&self) -> SoaSerial {
        self.soa.rdata.serial
    }

    /// A base name for persisted files for this instance.
    pub fn persistence_basename(&self, zone_name: &Name<Bytes>) -> String {
        format!("{zone_name}.L{}-SOA{}", self.id.0, self.serial().get())
    }

    /// The path to the persisted diff file, if any.
    ///
    /// If the diff for this instance (relative to the succeeding loaded
    /// instance) has been persisted, it will be stored at this path.
    pub fn diff_path(&self, zone_name: &Name<Bytes>, config: &crate::Config) -> Utf8PathBuf {
        let mut path = config
            .zone_state_dir
            .join(self.persistence_basename(zone_name))
            .into_string();
        path.push_str(".diff");
        path.into()
    }
}

/// The ID of a loaded instance.
#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct LoadedInstanceId(pub u64);

//----------- SignedInstance ---------------------------------------------------

/// A signed instance of a zone.
#[derive(Debug, Clone)]
pub struct SignedInstance {
    /// The ID of this instance.
    ///
    /// This includes the ID of the loaded instance this is relative to.
    pub id: SignedInstanceId,

    /// The SOA record of this instance.
    ///
    /// The primary purpose of this field is to provide the SOA serial. We still
    /// store the full SOA because it is used sometimes, e.g. for sending NOTIFY
    /// messages.
    pub soa: SoaRecord,

    /// The number of generated records.
    ///
    /// This is the number of records (RRSIG, NSEC, etc.) that were generated
    /// when building this instance. Notably, this includes the SOA record. The
    /// signed instance includes records from the loaded instance, but they are
    /// not counted here (for that see [`Self::num_loaded_records`]).
    pub num_generated_records: NonZeroU64,

    /// The number of records included from the loaded instance.
    ///
    /// This is the number of records from the associated loaded instance that
    /// are considered a part of the signed instance. This does not include
    /// DNSSEC records present in the loaded instance. Notably, this also
    /// excludes the loaded instance's SOA record.
    pub num_loaded_records: u64,
    //
    // TODO:
    // - How the instance was signed:
    //   - time, source, duration, size
    //   - Whether re-signing occurred, and what was re-signed.
    // - Basic details of the signed zone:
    //   - Total memory usage (excluding the loaded instance).
    // - DNSSEC details:
    //   - NSEC or NSEC3 records (incl. rollovers).
    //   - ZONEMD (incl. algorithms and rollovers).
    //   - Zone signing keys (incl. rollovers).
    //   - The earliest signature expiration time.
    //   - Extensions/overrides used during signing
    //     - See 'apex_{remove,extra}'.
}

impl SignedInstance {
    /// The SOA serial of this instance.
    pub fn serial(&self) -> SoaSerial {
        self.soa.rdata.serial
    }

    /// The total number of records in this instance.
    pub fn num_records(&self) -> NonZeroU64 {
        self.num_generated_records
            .checked_add(self.num_loaded_records)
            .unwrap()
    }

    /// A base name for persisted files for this instance.
    pub fn persistence_basename(&self, zone_name: &Name<Bytes>) -> String {
        format!(
            "{zone_name}.L{}-S{}-SOA{}",
            self.id.0.0,
            self.id.1,
            self.serial().get()
        )
    }

    /// The path to the persisted diff file, if any.
    ///
    /// If the diff for this instance (relative to the succeeding signed
    /// instance) has been persisted, it will be stored at this path.
    pub fn diff_path(&self, zone_name: &Name<Bytes>, config: &crate::Config) -> Utf8PathBuf {
        let mut path = config
            .zone_state_dir
            .join(self.persistence_basename(zone_name))
            .into_string();
        path.push_str(".diff");
        path.into()
    }
}

/// The ID of a signed instance.
#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct SignedInstanceId(pub LoadedInstanceId, pub u64);
